INSERT INTO `blog_posts` VALUES
('1b365a92-5e4a-466a-bee5-a03a4a9be0fd','pregnancy-month-by-month','متابعة-الحمل-شهرًا-بشهر-دليلك-الكامل','pregnancy-month-by-month',NULL,3,1,1,'/uploads/1787755121194-210c6f24.webp',NULL,'الحمل','Pregnancy','متابعة الحمل شهرًا بشهر: دليلك الكامل','Month-by-month pregnancy follow-up: your complete guide','جدول الزيارات والفحوصات الأساسية من أول اختبار حمل إيجابي وحتى يوم الولادة.','The essential visit and screening schedule from the first positive test to delivery day.','[\"تبدأ رحلة متابعة الحمل بمجرد ظهور نتيجة اختبار الحمل الإيجابية، حيث تُحدد الزيارة الأولى لتأكيد الحمل وتقدير عمره.\",\"تتضمن المتابعة الدورية فحوصات السونار، تحاليل الدم، ومتابعة ضغط الدم والوزن، لضمان سلامة الأم والجنين في كل مرحلة.\",\"الالتزام بجدول الزيارات يساعد على اكتشاف أي مضاعفات مبكرًا والتعامل معها بأمان.\"]','[\"The pregnancy journey begins the moment a test turns positive, with a first visit to confirm the pregnancy and estimate its age.\",\"Regular follow-up includes ultrasound scans, blood tests, and monitoring of blood pressure and weight to keep mother and baby safe at every stage.\",\"Keeping to the visit schedule helps catch any complications early and manage them safely.\"]','','','','','2026-07-15 11:22:25','2026-07-20 08:52:03'),
('50229ace-8a35-41df-be75-3da83d82c908','endometriosis-diagnosis','بطانة-الرحم-المهاجرة-لماذا-يتأخر-التشخيص؟','endometriosis-diagnosis',NULL,4,1,1,'/uploads/1787755121553-f9916a18.webp',NULL,'بطانة الرحم','Endometriosis','بطانة الرحم المهاجرة: لماذا يتأخر التشخيص؟','Endometriosis: why is diagnosis so often delayed?','آلام دورة شديدة ليست أمرًا طبيعيًا دائمًا — متى تشكين في بطانة الرحم المهاجرة وما خيارات العلاج؟','Severe period pain is not always normal — when to suspect endometriosis and what the treatment options are.','[\"بطانة الرحم المهاجرة حالة مزمنة تنمو فيها أنسجة مشابهة لبطانة الرحم خارجه، مسببة آلامًا شديدة وأحيانًا مشاكل في الخصوبة.\",\"يتأخر التشخيص غالبًا لأن الأعراض تُنسب خطأً إلى آلام الدورة الطبيعية. التشخيص الدقيق يتطلب خبرة وفحوصات متخصصة.\",\"تتراوح خيارات العلاج بين الأدوية والتدخل الجراحي حسب شدة الحالة ورغبة المريضة في الإنجاب.\"]','[\"Endometriosis is a chronic condition in which tissue similar to the uterine lining grows outside it, causing severe pain and sometimes fertility problems.\",\"Diagnosis is often delayed because symptoms are wrongly attributed to normal period pain. An accurate diagnosis requires experience and specialized testing.\",\"Treatment options range from medication to surgery, depending on severity and the patient\'s fertility goals.\"]','','','','','2026-07-15 11:22:25','2026-07-20 08:52:03'),
('51fbe540-ef03-42df-a6f8-98035faff222','fibroids-symptoms-surgery','الأورام-الليفية-الأعراض-ومتى-يجب-التدخل-الجراحي','fibroids-symptoms-surgery',NULL,2,1,1,'/uploads/1787755120531-2dbb9511.webp',NULL,'الأورام الليفية','Fibroids','الأورام الليفية: الأعراض ومتى يجب التدخل الجراحي','Fibroids: symptoms and when surgery is needed','أكثر من 99% من الأورام الليفية حميدة، لكن تجاهلها قد يؤدي إلى مضاعفات — تعرفي على العلامات التي لا يجب إغفالها.','Over 99% of fibroids are benign, but ignoring them can lead to complications — the signs you should never overlook.','[\"الأورام الليفية هي أورام حميدة تنمو في جدار الرحم، وتصيب نسبة كبيرة من النساء في سن الإنجاب دون أن تسبب أعراضًا في كثير من الأحيان.\",\"تشمل العلامات التي تستدعي استشارة الطبيب: النزيف الغزير، آلام الحوض المستمرة، وصعوبة الحمل. التدخل الجراحي يصبح ضروريًا عند تأثير الورم على الخصوبة أو جودة الحياة.\",\"الخبرة النادرة في استئصال الأورام المعقدة مع الحفاظ على الرحم تمنح المريضة أفضل فرصة للإنجاب مستقبلًا.\"]','[\"Fibroids are benign tumors that grow in the uterine wall and affect a large share of women of reproductive age, often without symptoms.\",\"Signs that warrant a consultation include heavy bleeding, persistent pelvic pain, and difficulty conceiving. Surgery becomes necessary when a fibroid affects fertility or quality of life.\",\"Rare skill in removing complex fibroids while preserving the uterus gives the patient the best chance of future pregnancy.\"]','','','','','2026-07-15 11:22:25','2026-07-20 08:52:03'),
('62d31e9d-ea4b-4efc-b419-c2444eda53d6','routine-gynecological-checkups','الفحص-الدوري-النسائي-متى-وماذا-يشمل؟','routine-gynecological-checkups',NULL,6,1,1,'/uploads/1787755120878-33321e7a.webp',NULL,'صحة المرأة','Women’s health','الفحص الدوري النسائي: متى وماذا يشمل؟','Routine gynecological checkups: when and what?','الوقاية خير من العلاج — دليلك للفحوصات الدورية الأساسية لكل امرأة في كل مرحلة عمرية.','Prevention is better than cure — your guide to the essential routine screenings for every woman at every age.','[\"الفحص النسائي الدوري ركيزة أساسية للوقاية، إذ يساعد على اكتشاف المشكلات مبكرًا قبل تطورها.\",\"يشمل الفحص عادة تقييمًا سريريًا، مسحة عنق الرحم، وفحص السونار حسب العمر والحالة.\",\"يُنصح كل امرأة بإجراء فحص دوري سنوي على الأقل، مع زيادة التردد حسب توصية الطبيب.\"]','[\"The routine gynecological checkup is a cornerstone of prevention, helping detect problems early before they progress.\",\"The exam typically includes a clinical assessment, a cervical smear, and ultrasound depending on age and condition.\",\"Every woman is advised to have at least an annual checkup, with more frequent visits as recommended by her doctor.\"]','','','','','2026-07-15 11:22:25','2026-07-20 08:52:03'),
('6feccabd-0e27-4039-929a-db5a158b28a2','pain-free-delivery','كل-ما-تريدين-معرفته-عن-الولادة-بدون-ألم','pain-free-delivery','2d4dfa9c-e618-4133-953a-0e5d059cc7a1',1,1,1,'/uploads/1787755120261-c0de4ef4.webp',NULL,'الولادة','Delivery','كل ما تريدين معرفته عن الولادة بدون ألم','Everything you need to know about pain-free delivery','كيف تتم الولادة بدون ألم؟ ومتى تُستخدم؟ وهل هي آمنة عليك وعلى طفلك؟ إجابات شاملة من واقع آلاف الحالات.','How does pain-free delivery work? When is it used? Is it safe for you and your baby? Answers drawn from thousands of cases.','[\"الولادة بدون ألم هي مجموعة من التقنيات الطبية الحديثة التي تهدف إلى تقليل أو إزالة الألم أثناء الولادة الطبيعية والقيصرية، مع الحفاظ على سلامة الأم والجنين.\",\"تعتمد التقنية الأكثر شيوعًا على التخدير النصفي (الإبيدورال)، الذي يسمح للأم بالبقاء واعية أثناء الولادة والاستمتاع بلحظة استقبال طفلها دون معاناة.\",\"من واقع أكثر من 10,000 حالة ولادة بدون ألم، أثبتت هذه التقنيات أمانها العالي عند إجرائها على يد فريق طبي متخصص وفي بيئة مجهزة بالكامل.\"]','[\"Pain-free delivery is a set of modern medical techniques designed to reduce or eliminate pain during natural and cesarean births, while keeping mother and baby safe.\",\"The most common approach relies on epidural anesthesia, which lets the mother stay awake and enjoy the moment of meeting her baby without suffering.\",\"Across more than 10,000 pain-free deliveries, these techniques have proven highly safe when performed by a specialized team in a fully equipped setting.\"]','','','','','2026-07-15 11:22:25','2026-07-20 08:52:03'),
('e1240d24-c073-4f37-a996-1570d8882610','tummy-tuck-cesarean','شد-البطن-مع-القيصرية-هل-هو-مناسب-لكِ؟','tummy-tuck-cesarean',NULL,5,0,0,'/uploads/1787755121930-be36a321.webp',NULL,'القيصرية','Cesarean','شد البطن مع القيصرية: هل هو مناسب لكِ؟','Tummy tuck with cesarean: is it right for you?','إجراء واحد يجمع ولادة آمنة واستعادة رشاقة الجسم — الشروط والمزايا وما يجب معرفته قبل القرار.','One procedure combining a safe delivery with regaining your figure — conditions, benefits, and what to know first.','<p>يمكن إجراء عملية شد البطن مع الولادة القيصرية في جلسة واحدة، مما يوفر على الأم عملية جراحية منفصلة وفترة نقاهة إضافية.</p><p>يناسب هذا الإجراء النساء اللاتي أكملن حجم عائلتهن ويرغبن في استعادة شكل البطن بعد الحمل.</p><p>يُتخذ القرار بعد تقييم دقيق للحالة الصحية للأم والجنين لضمان أعلى درجات الأمان.</p>','<p>A tummy tuck can be performed together with a cesarean in a single session, sparing the mother a separate operation and extra recovery time.</p><p>This procedure suits women who have completed their family and wish to restore their abdominal shape after pregnancy.</p><p>The decision is made after a careful assessment of the health of mother and baby to ensure the highest level of safety.</p>','','','','','2026-07-15 11:22:25','2026-08-09 11:24:01');
