INSERT INTO `services` VALUES
('21e223b6-fb31-4d02-9580-9af938c2da57','removal-of-complex-fibroids-combined-with-body-contouring-or-abdominoplasty','استئصال-الأورام-الليفية-المعقدة-مع-نحت-القوام-او-شد-البطن','removal-of-complex-fibroids-combined-with-body-contouring-or-abdominoplasty','73b6f1f5-fbfc-43f2-b2c1-6463aafa663d',NULL,14,1,1,'','/uploads/1787755098178-557d9680.webp','/uploads/1787755098777-888b8a9d.webp','auto','auto','جراحة أورام','Tumor surgery','استئصال الأورام الليفية المعقدة مع نحت القوام او شد البطن','Removal of complex fibroids combined with body contouring or abdominoplasty','استئصال الأورام المعقدة مع الحفاظ على الرحم — الخيار الأفضل لمن تعانين من الأعراض وترغبين في الإنجاب مستقبلًا.','Removal of complex fibroids while preserving the uterus — the best option for women with symptoms who want children in the future.','مهارة نادرة في استئصال الأورام الليفية المعقدة مع الحفاظ على الرحم والقدرة على الإنجاب.','Rare skill in removing complex fibroids while preserving the uterus and fertility.','الأورام الليفية أورام حميدة شائعة، لكن بعض الحالات المعقدة تتطلب خبرة جراحية نادرة لاستئصالها مع الحفاظ على الرحم والقدرة على الإنجاب. نتميز بمهارة عالية في أصعب هذه الحالات.','Fibroids are common benign tumors, but some complex cases require rare surgical skill to remove them while preserving the uterus and fertility. We are distinguished by high skill in the most difficult of these cases.','[{\"body_ar\":\"يصبح التدخل ضروريًا عند وجود نزيف غزير، أو آلام مستمرة، أو تأثير على الخصوبة أو على الحمل. نقيّم كل حالة على حدة قبل اتخاذ القرار.\",\"body_en\":\"Surgery becomes necessary with heavy bleeding, persistent pain, or an effect on fertility or pregnancy. We assess each case individually before deciding.\",\"heading_ar\":\"متى يجب التدخل؟\",\"heading_en\":\"When is surgery needed?\"}]','[{\"ar\":\"الحفاظ على الرحم والقدرة على الإنجاب\",\"en\":\"Preserving the uterus and fertility\"}]','[{\"a_ar\":\"في الحالات المناسبة نحافظ على الرحم لتظل فرص الإنجاب قائمة.\",\"a_en\":\"In suitable cases we preserve the uterus so fertility remains possible.\",\"q_ar\":\"هل سأتمكن من الإنجاب بعد العملية؟\",\"q_en\":\"Will I be able to conceive after surgery?\"}]','استئصال الأورام الليفية المعقدة مع نحت القوام او شد البطن | د. أحمد مرزوق','Removal of complex fibroids combined with body contouring or abdominoplasty | Dr. Ahmed Marzouk','استئصال الأورام الليفية المعقدة مع الحفاظ على الرحم والقدرة على الإنجاب مع د. أحمد مرزوق.','Complex fibroid removal while preserving the uterus and fertility with Dr. Ahmed Marzouk.','2026-08-05 13:14:53','2026-08-09 11:48:05'),
('31332bf0-1474-471e-b3ec-058faa3f8f94','pelvic-adhesiolysis','فك-التصاقات-البطن-والحوض','pelvic-adhesiolysis','73b6f1f5-fbfc-43f2-b2c1-6463aafa663d',NULL,13,1,1,'⟡','/uploads/1787755095999-0369d9bc.webp','/uploads/1787755096292-8fd12619.webp','auto','auto','جراحة أورام','Tumor surgery','فك التصاقات البطن والحوض','Abdominal & Pelvic Adhesiolysis','فك التصاقات البطن والحوض بالمنظار لتخفيف الألم وتحسين الخصوبة.','Laparoscopic release of abdominal and pelvic adhesions to relieve pain and improve fertility.','علاج دقيق للالتصاقات لاستعادة الراحة والوظيفة الطبيعية.','Precise treatment of adhesions to restore comfort and normal function.','قد تنشأ الالتصاقات بعد الجراحات أو الالتهابات وتسبب آلامًا مزمنة أو مشاكل في الخصوبة. نفكّها بالمنظار بدقة لاستعادة الحركة الطبيعية للأعضاء.','Adhesions may form after surgery or infection and cause chronic pain or fertility problems. We release them laparoscopically with precision to restore the normal movement of the organs.','[{\"body_ar\":\"تنشأ غالبًا بعد العمليات الجراحية أو الالتهابات الحوضية أو بطانة الرحم المهاجرة.\",\"body_en\":\"They usually form after surgery, pelvic infections, or endometriosis.\",\"heading_ar\":\"أسباب الالتصاقات\",\"heading_en\":\"Causes of adhesions\"},{\"body_ar\":\"نفكّ الالتصاقات بعناية لتخفيف الألم وتحسين فرص الحمل مع تقليل احتمال تكوّنها من جديد.\",\"body_en\":\"We carefully release the adhesions to relieve pain and improve fertility while reducing the chance of them reforming.\",\"heading_ar\":\"العلاج بالمنظار\",\"heading_en\":\"Laparoscopic treatment\"}]','[{\"ar\":\"تخفيف الألم المزمن\",\"en\":\"Relief from chronic pain\"},{\"ar\":\"تحسين فرص الإنجاب\",\"en\":\"Improved fertility prospects\"},{\"ar\":\"جراحة دقيقة بالمنظار\",\"en\":\"Precise laparoscopic surgery\"}]','[{\"a_ar\":\"نستخدم تقنيات دقيقة لتقليل عودتها، مع متابعة فردية لكل حالة.\",\"a_en\":\"We use precise techniques to reduce recurrence, with individual follow-up for each case.\",\"q_ar\":\"هل تعود الالتصاقات بعد فكها؟\",\"q_en\":\"Do adhesions return after release?\"},{\"a_ar\":\"في كثير من الحالات نعم، خاصة عندما تكون الالتصاقات سبب صعوبة الحمل.\",\"a_en\":\"In many cases yes, especially when adhesions are the cause of difficulty conceiving.\",\"q_ar\":\"هل تحسّن العملية الخصوبة؟\",\"q_en\":\"Does the surgery improve fertility?\"}]','فك التصاقات البطن والحوض | د. أحمد مرزوق','Pelvic Adhesiolysis | Dr. Ahmed Marzouk','فك التصاقات البطن والحوض بالمنظار لتخفيف الألم وتحسين الخصوبة مع د. أحمد مرزوق.','Laparoscopic release of abdominal and pelvic adhesions to relieve pain and improve fertility with Dr. Ahmed Marzouk.','2026-07-26 11:44:44','2026-08-09 11:47:33'),
('3dfd6bb9-6fe4-4d8a-84c0-dd385667915c','pain-free-natural-birth','الولادة-الطبيعية-بدون-ألم','pain-free-natural-birth','2300aca2-e93f-48d3-8316-6f683a6660ac',NULL,3,1,1,'♡','/uploads/1787755093363-3977d3fa.webp','/uploads/1787755093591-524756a1.webp','auto','span 2','ولادة','Birth','الولادة الطبيعية بدون ألم','Pain-Free Natural Birth','تجربة ولادة طبيعية هادئة بدون معاناة، مع متابعة دقيقة طوال فترة الحمل وحتى أول احتضان لطفلك.','A calm natural birth without suffering, with careful follow-up throughout pregnancy until your first embrace.','ولادة طبيعية هادئة بدون معاناة، مع متابعة دقيقة قبل الولادة وحتى أول احتضان.','A calm natural birth without suffering, with careful follow-up through the first embrace.','نؤمن أن الولادة الطبيعية يمكن أن تكون تجربة هادئة وجميلة بدلًا من أن تكون مصدرًا للخوف. من خلال التخدير النصفي (الإبيدورال) والمتابعة الدقيقة، نساعدك على المرور بتجربة ولادة آمنة وبأقل قدر ممكن من الألم.','We believe natural birth can be a calm, beautiful experience rather than a source of fear. Through epidural anesthesia and careful monitoring, we help you go through a safe delivery with the least pain possible.','[{\"body_ar\":\"يسمح لكِ التخدير النصفي بالبقاء واعية ومشاركة في لحظة الولادة مع تخفيف الألم بشكل كبير، وهو آمن على الأم والجنين عند تطبيقه بشكل صحيح.\",\"body_en\":\"The epidural lets you stay awake and part of the moment while greatly relieving pain — safe for mother and baby when applied correctly.\",\"heading_ar\":\"التخدير النصفي (الإبيدورال)\",\"heading_en\":\"Epidural anesthesia\"},{\"body_ar\":\"نتابع معكِ الحمل شهرًا بشهر لضمان جاهزيتك ليوم الولادة، مع خطة واضحة لكل مرحلة وطمأنة مستمرة.\",\"body_en\":\"We follow your pregnancy month by month to ensure you\'re ready for delivery day, with a clear plan for each stage and continuous reassurance.\",\"heading_ar\":\"متابعة الحمل حتى الولادة\",\"heading_en\":\"Follow-up until delivery\"},{\"body_ar\":\"نوفر بيئة هادئة ودعمًا كاملًا قبل وأثناء وبعد الولادة، لأن راحتك النفسية جزء أساسي من التجربة.\",\"body_en\":\"We provide a calm environment and full support before, during and after birth — your peace of mind is an essential part of the experience.\",\"heading_ar\":\"بيئة داعمة ومطمئنة\",\"heading_en\":\"A supportive, reassuring environment\"}]','[{\"ar\":\"ألم أقل وتجربة أكثر هدوءًا\",\"en\":\"Less pain and a calmer experience\"},{\"ar\":\"بقاؤك واعية أثناء الولادة\",\"en\":\"Staying awake during birth\"},{\"ar\":\"متابعة دقيقة طوال الحمل\",\"en\":\"Careful follow-up throughout pregnancy\"},{\"ar\":\"تعافٍ أسرع من القيصرية عادةً\",\"en\":\"Usually faster recovery than a cesarean\"}]','[{\"a_ar\":\"عند تطبيقه بشكل صحيح فهو آمن ولا يؤثر سلبًا على الطفل.\",\"a_en\":\"When applied correctly it is safe and does not harm the baby.\",\"q_ar\":\"هل الإبيدورال يؤثر على الطفل؟\",\"q_en\":\"Does the epidural affect the baby?\"},{\"a_ar\":\"نقيّم حالتك ونناقش الخيار الأنسب لكِ ولطفلك معًا.\",\"a_en\":\"We assess your case and discuss the most suitable option for you and your baby together.\",\"q_ar\":\"هل يمكنني اختيار الولادة الطبيعية؟\",\"q_en\":\"Can I choose natural birth?\"},{\"a_ar\":\"نعطيكِ إرشادات واضحة مسبقًا حول علامات الولادة ومتى تتوجهين إلينا.\",\"a_en\":\"We give you clear guidance in advance about the signs of labor and when to come in.\",\"q_ar\":\"متى أذهب للعيادة عند بدء الطلق؟\",\"q_en\":\"When should I come in when labor starts?\"}]','الولادة الطبيعية بدون ألم | د. أحمد مرزوق','Pain-Free Natural Birth | Dr. Ahmed Marzouk','ولادة طبيعية بدون ألم بالتخدير النصفي ومتابعة دقيقة للحمل مع د. أحمد مرزوق.','Pain-free natural delivery with epidural anesthesia and careful pregnancy follow-up with Dr. Ahmed Marzouk.','2026-07-15 11:22:25','2026-08-09 11:55:04'),
('48ffd580-3427-487d-a4e7-a3e6442347b4','chocolate-cyst-removal','استئصال-الأكياس-الشوكولاتية','chocolate-cyst-removal','73b6f1f5-fbfc-43f2-b2c1-6463aafa663d',NULL,12,1,1,'✜','/uploads/1787755097702-d27dd9b6.webp','/uploads/1787755097979-5a666421.webp','auto','auto','جراحة أورام','Tumor surgery','استئصال الأكياس الشوكولاتية','Chocolate Cyst Removal','إزالة الأكياس الشوكولاتية (بطانة الرحم على المبيض) مع الحفاظ على الخصوبة.','Removing chocolate cysts (ovarian endometriomas) while preserving fertility.','علاج دقيق للأكياس الشوكولاتية مع الحفاظ على المبيض.','Precise treatment of chocolate cysts while preserving the ovary.','الأكياس الشوكولاتية نوع من بطانة الرحم المهاجرة يتكوّن على المبيض وقد يؤثر على الخصوبة. نزيلها بدقة بالمنظار مع الحفاظ على أنسجة المبيض السليمة.','Chocolate cysts are a form of endometriosis that forms on the ovary and can affect fertility. We remove them precisely by laparoscopy while preserving healthy ovarian tissue.','[{\"body_ar\":\"قد تؤثر الأكياس الشوكولاتية على مخزون المبيض والخصوبة، لذا نتعامل معها بعناية للحفاظ على أكبر قدر من النسيج السليم.\",\"body_en\":\"Chocolate cysts may affect ovarian reserve and fertility, so we handle them carefully to preserve as much healthy tissue as possible.\",\"heading_ar\":\"تأثيرها على الخصوبة\",\"heading_en\":\"Effect on fertility\"},{\"body_ar\":\"نزيل الكيس بالمنظار بدقة عالية لتقليل الضرر على المبيض وتحسين النتائج.\",\"body_en\":\"We remove the cyst laparoscopically with high precision to minimize damage to the ovary and improve outcomes.\",\"heading_ar\":\"العلاج بالمنظار\",\"heading_en\":\"Laparoscopic treatment\"}]','[{\"ar\":\"الحفاظ على مخزون المبيض\",\"en\":\"Preserving ovarian reserve\"},{\"ar\":\"تخفيف الألم المزمن\",\"en\":\"Relief from chronic pain\"},{\"ar\":\"تحسين فرص الإنجاب\",\"en\":\"Improved fertility prospects\"}]','[{\"a_ar\":\"أكياس على المبيض ناتجة عن بطانة الرحم المهاجرة وتحتوي على دم قديم داكن.\",\"a_en\":\"Cysts on the ovary caused by endometriosis, containing old dark blood.\",\"q_ar\":\"ما الأكياس الشوكولاتية؟\",\"q_en\":\"What are chocolate cysts?\"},{\"a_ar\":\"قد تتكرر أحيانًا، لذا نضع خطة متابعة فردية لكل حالة.\",\"a_en\":\"They can sometimes recur, so we set an individual follow-up plan for each case.\",\"q_ar\":\"هل تتكرر بعد العلاج؟\",\"q_en\":\"Can they recur after treatment?\"}]','استئصال الأكياس الشوكولاتية | د. أحمد مرزوق','Chocolate Cyst Removal | Dr. Ahmed Marzouk','استئصال الأكياس الشوكولاتية بالمنظار مع الحفاظ على المبيض والخصوبة مع د. أحمد مرزوق.','Laparoscopic chocolate cyst removal while preserving the ovary and fertility with Dr. Ahmed Marzouk.','2026-07-26 11:44:44','2026-08-09 11:41:21'),
('4e6696c2-16f6-4eaf-b571-07decf16bca7','complex-fibroid-removal','استئصال-الأورام-الليفية-المعقدة','complex-fibroid-removal','73b6f1f5-fbfc-43f2-b2c1-6463aafa663d',NULL,1,1,1,'❀','/uploads/1787755094612-2286df41.webp','/uploads/1787755094990-01bbc227.webp','auto','auto','جراحة أورام','Tumor surgery','استئصال الأورام الليفية المعقدة','Complex Fibroid Removal','استئصال الأورام المعقدة مع الحفاظ على الرحم — الخيار الأفضل لمن تعانين من الأعراض وترغبين في الإنجاب مستقبلًا.','Removal of complex fibroids while preserving the uterus — the best option for women with symptoms who want children in the future.','مهارة نادرة في استئصال الأورام الليفية المعقدة مع الحفاظ على الرحم والقدرة على الإنجاب.','Rare skill in removing complex fibroids while preserving the uterus and fertility.','الأورام الليفية أورام حميدة شائعة، لكن بعض الحالات المعقدة تتطلب خبرة جراحية نادرة لاستئصالها مع الحفاظ على الرحم والقدرة على الإنجاب. نتميز بمهارة عالية في أصعب هذه الحالات.','Fibroids are common benign tumors, but some complex cases require rare surgical skill to remove them while preserving the uterus and fertility. We are distinguished by high skill in the most difficult of these cases.','[{\"body_ar\":\"يصبح التدخل ضروريًا عند وجود نزيف غزير، أو آلام مستمرة، أو تأثير على الخصوبة أو على الحمل. نقيّم كل حالة على حدة قبل اتخاذ القرار.\",\"body_en\":\"Surgery becomes necessary with heavy bleeding, persistent pain, or an effect on fertility or pregnancy. We assess each case individually before deciding.\",\"heading_ar\":\"متى يجب التدخل؟\",\"heading_en\":\"When is surgery needed?\"},{\"body_ar\":\"هدفنا الأول في الحالات المناسبة هو استئصال الورم مع الحفاظ على الرحم، لتظل قدرتك على الإنجاب محفوظة حتى بعد إزالة أورام كبيرة أو معقدة.\",\"body_en\":\"Our primary goal in suitable cases is to remove the fibroid while preserving the uterus, keeping your fertility intact even after removing large or complex tumors.\",\"heading_ar\":\"الحفاظ على الرحم\",\"heading_en\":\"Preserving the uterus\"},{\"body_ar\":\"من بين إنجازاتنا استئصال ورم بوزن 14 كجم مع الحفاظ على الجنين — دليل على القدرة على التعامل مع أصعب الحالات بأمان.\",\"body_en\":\"Among our milestones is removing a 14 kg tumor while preserving the fetus — proof of the ability to handle the hardest cases safely.\",\"heading_ar\":\"خبرة في الحالات النادرة\",\"heading_en\":\"Experience with rare cases\"}]','[{\"ar\":\"الحفاظ على الرحم والقدرة على الإنجاب\",\"en\":\"Preserving the uterus and fertility\"},{\"ar\":\"خبرة في أصعب وأكبر الحالات\",\"en\":\"Experience with the hardest, largest cases\"},{\"ar\":\"تخفيف الأعراض والنزيف\",\"en\":\"Relief from symptoms and bleeding\"},{\"ar\":\"خطة علاج فردية لكل حالة\",\"en\":\"An individual treatment plan for each case\"}]','[{\"a_ar\":\"في الحالات المناسبة نحافظ على الرحم لتظل فرص الإنجاب قائمة.\",\"a_en\":\"In suitable cases we preserve the uterus so fertility remains possible.\",\"q_ar\":\"هل سأتمكن من الإنجاب بعد العملية؟\",\"q_en\":\"Will I be able to conceive after surgery?\"},{\"a_ar\":\"لا، كثير منها لا يسبب أعراضًا. الجراحة للحالات التي تسبب مشاكل فقط.\",\"a_en\":\"No — many cause no symptoms. Surgery is only for those causing problems.\",\"q_ar\":\"هل كل الأورام الليفية تحتاج جراحة؟\",\"q_en\":\"Do all fibroids need surgery?\"},{\"a_ar\":\"نعم، تتوفر استشارة فيديو لحالات الأورام الليفية توفيرًا للوقت والمسافة.\",\"a_en\":\"Yes — video consultations are available for fibroid cases, saving time and distance.\",\"q_ar\":\"هل الاستشارة عن بُعد متاحة؟\",\"q_en\":\"Is a remote consultation available?\"}]','استئصال الأورام الليفية المعقدة | د. أحمد مرزوق','Complex Fibroid Removal | Dr. Ahmed Marzouk','استئصال الأورام الليفية المعقدة مع الحفاظ على الرحم والقدرة على الإنجاب مع د. أحمد مرزوق.','Complex fibroid removal while preserving the uterus and fertility with Dr. Ahmed Marzouk.','2026-07-15 11:22:25','2026-08-09 11:40:00'),
('4e7f2dc8-d6ad-4935-82ef-c2035fc02729','pain-free-cesarean','الولادة-القيصرية-بدون-ألم','pain-free-cesarean','2300aca2-e93f-48d3-8316-6f683a6660ac',NULL,2,1,1,'⊕','/uploads/1787755092638-a8c48570.webp','/uploads/1787755092982-417945cd.webp','span 2','span 2','ولادة','Birth','الولادة القيصرية بدون ألم','Pain-Free Cesarean Birth','ولادة قيصرية آمنة تجنب النساء المعرضات للخطر أي مضاعفات، بتقنيات حديثة تجعل التجربة بدون ألم وبأجمل الذكريات.','A safe cesarean that protects at-risk mothers from complications — modern techniques for a pain-free experience and beautiful memories.','تجربة قيصرية آمنة ومطمئنة بدون ألم، بأحدث التقنيات التي تحفظ لكِ أجمل لحظات استقبال طفلك.','A safe, reassuring cesarean experience without pain — the latest techniques that preserve your most beautiful first moments.','الولادة القيصرية بدون ألم هي خيار آمن ومدروس للنساء اللاتي تستدعي حالتهن الطبية إجراء قيصرية، سواء لأسباب متعلقة بوضع الجنين أو صحة الأم. نحرص على أن تكون التجربة خالية من الألم والتوتر قدر الإمكان، مع أعلى معايير الأمان للأم والجنين.','Pain-free cesarean delivery is a safe, well-considered option for women whose medical condition calls for a cesarean — whether due to the baby\'s position or the mother\'s health. We make the experience as free of pain and anxiety as possible, with the highest safety standards for both mother and baby.','[{\"body_ar\":\"تُنصح القيصرية في حالات مثل وضع الجنين المقعدي، أو تعدد الأجنة، أو بعض حالات المشيمة، أو عندما تكون الولادة الطبيعية غير آمنة للأم أو الجنين. يتم اتخاذ القرار بعد تقييم دقيق وشرح كامل لكل الخيارات.\",\"body_en\":\"A cesarean is advised in cases such as a breech baby, multiple pregnancies, certain placenta conditions, or when natural delivery isn\'t safe for mother or baby. The decision is made after careful assessment and a full explanation of every option.\",\"heading_ar\":\"متى تُنصح القيصرية؟\",\"heading_en\":\"When is a cesarean recommended?\"},{\"body_ar\":\"نعتمد على تقنيات التخدير الحديثة التي تسمح للأم بالبقاء واعية أثناء الولادة والاستمتاع بلحظة استقبال طفلها، مع إدارة دقيقة للألم بعد العملية لتعافٍ سريع ومريح.\",\"body_en\":\"We rely on modern anesthesia techniques that let the mother stay awake and enjoy meeting her baby, with careful post-operative pain management for a fast, comfortable recovery.\",\"heading_ar\":\"كيف نجعلها بدون ألم؟\",\"heading_en\":\"How we make it pain-free\"},{\"body_ar\":\"نضع خطة تعافٍ فردية لكل أم تشمل المتابعة الدقيقة للجرح، ونصائح الحركة المبكرة الآمنة، والدعم الكامل خلال الأيام الأولى لضمان عودة سريعة لحياتك الطبيعية.\",\"body_en\":\"We set an individual recovery plan for each mother — careful wound follow-up, safe early-mobility guidance, and full support through the first days for a quick return to normal life.\",\"heading_ar\":\"التعافي بعد الولادة\",\"heading_en\":\"Recovery after delivery\"}]','[{\"ar\":\"تجربة بدون ألم من أول لحظة\",\"en\":\"A pain-free experience from the first moment\"},{\"ar\":\"أعلى معايير الأمان للأم والجنين\",\"en\":\"Highest safety standards for mother and baby\"},{\"ar\":\"إمكانية إجراء شد البطن مع القيصرية\",\"en\":\"Option to combine a tummy tuck with the cesarean\"},{\"ar\":\"متابعة دقيقة وتعافٍ سريع\",\"en\":\"Careful follow-up and rapid recovery\"}]','[{\"a_ar\":\"نعم، عند إجرائها على يد فريق متخصص وفي بيئة مجهزة، تُعد من أكثر الإجراءات أمانًا.\",\"a_en\":\"Yes — performed by a specialized team in a fully equipped setting, it is among the safest procedures.\",\"q_ar\":\"هل القيصرية بدون ألم آمنة؟\",\"q_en\":\"Is a pain-free cesarean safe?\"},{\"a_ar\":\"تتعافى معظم الأمهات تدريجيًا خلال أسابيع قليلة مع اتباع خطة التعافي الموصى بها.\",\"a_en\":\"Most mothers recover gradually over a few weeks by following the recommended recovery plan.\",\"q_ar\":\"متى أستطيع العودة لنشاطي الطبيعي؟\",\"q_en\":\"When can I return to normal activity?\"},{\"a_ar\":\"نناقش معكِ كل التفاصيل مسبقًا لتوفير تجربة مطمئنة تناسب رغباتك قدر الإمكان.\",\"a_en\":\"We discuss every detail with you in advance to provide a reassuring experience that fits your wishes as much as possible.\",\"q_ar\":\"هل يمكن حضور زوجي؟\",\"q_en\":\"Can my husband attend?\"}]','الولادة القيصرية بدون ألم | د. أحمد مرزوق','Pain-Free Cesarean Birth | Dr. Ahmed Marzouk','ولادة قيصرية بدون ألم بأحدث تقنيات التخدير وأعلى معايير الأمان مع د. أحمد مرزوق — استشاري النساء والتوليد.','Pain-free cesarean delivery with the latest anesthesia techniques and highest safety standards with Dr. Ahmed Marzouk, OB-GYN consultant.','2026-07-15 11:22:25','2026-08-09 11:44:25'),
('91ab25fe-ba53-431a-aa66-c62ab7ceeb86','ovarian-cyst-removal','استئصال-أكياس-من-على-المبيض','ovarian-cyst-removal','73b6f1f5-fbfc-43f2-b2c1-6463aafa663d',NULL,11,1,1,'◈','/uploads/1787755096589-a986016b.webp','/uploads/1787755096892-58fbff42.webp','auto','auto','جراحة أورام','Tumor surgery','استئصال أكياس المبيض','Ovarian Cyst Removal','إزالة أكياس المبيض مع الحفاظ على المبيض ووظيفته والخصوبة كلما أمكن.','Removing ovarian cysts while preserving the ovary, its function and fertility whenever possible.','استئصال دقيق لأكياس المبيض مع الحفاظ على المبيض السليم.','Precise removal of ovarian cysts while preserving the healthy ovary.','أكياس المبيض شائعة وكثير منها يزول تلقائيًا، لكن بعضها يستدعي التدخل الجراحي. نحرص على إزالة الكيس مع الحفاظ على أنسجة المبيض السليمة ووظيفته.','Ovarian cysts are common and many resolve on their own, but some require surgery. We remove the cyst while preserving the healthy ovarian tissue and its function.','[{\"body_ar\":\"عند كبر حجمه أو استمراره أو تسببه في آلام أو الاشتباه في طبيعته، نقرر التدخل بعد تقييم دقيق.\",\"body_en\":\"When it is large, persistent, painful, or its nature is suspicious, we decide on surgery after careful assessment.\",\"heading_ar\":\"متى يحتاج الكيس لجراحة؟\",\"heading_en\":\"When does a cyst need surgery?\"},{\"body_ar\":\"نستأصل الكيس مع الحفاظ على أكبر قدر من نسيج المبيض السليم لحماية الخصوبة.\",\"body_en\":\"We remove the cyst while preserving as much healthy ovarian tissue as possible to protect fertility.\",\"heading_ar\":\"الحفاظ على المبيض\",\"heading_en\":\"Preserving the ovary\"}]','[{\"ar\":\"الحفاظ على المبيض والخصوبة\",\"en\":\"Preserving the ovary and fertility\"},{\"ar\":\"تخفيف الألم والأعراض\",\"en\":\"Relief from pain and symptoms\"},{\"ar\":\"تقييم دقيق وآمن\",\"en\":\"Careful, safe assessment\"}]','[{\"a_ar\":\"نحرص على الحفاظ على المبيض ووظيفته لتظل الخصوبة محمية قدر الإمكان.\",\"a_en\":\"We aim to preserve the ovary and its function so fertility stays protected as much as possible.\",\"q_ar\":\"هل تؤثر العملية على الخصوبة؟\",\"q_en\":\"Does the surgery affect fertility?\"},{\"a_ar\":\"لا، كثير منها يزول تلقائيًا؛ نتدخل فقط عند الحاجة.\",\"a_en\":\"No, many resolve on their own; we operate only when needed.\",\"q_ar\":\"هل كل الأكياس تحتاج جراحة؟\",\"q_en\":\"Do all cysts need surgery?\"}]','استئصال أكياس المبيض | د. أحمد مرزوق','Ovarian Cyst Removal | Dr. Ahmed Marzouk','استئصال أكياس المبيض مع الحفاظ على المبيض والخصوبة مع د. أحمد مرزوق.','Ovarian cyst removal while preserving the ovary and fertility with Dr. Ahmed Marzouk.','2026-07-26 11:44:44','2026-08-09 11:41:10'),
('ad68be7b-c482-48c3-b6fc-b32cb02bd768','laparoscopic-hysterectomy','استئصال-الرحم-بالمنظار','laparoscopic-hysterectomy','73b6f1f5-fbfc-43f2-b2c1-6463aafa663d',NULL,10,1,1,'⚕','/uploads/1787755099162-e07fa336.webp','/uploads/1787755099455-bd4de5b1.webp','auto','auto','جراحة أورام','Tumor surgery','استئصال الرحم بالمنظار','Laparoscopic Hysterectomy','استئصال الرحم بالمنظار عند الحاجة الطبية بجروح صغيرة وتعافٍ أسرع.','Laparoscopic hysterectomy when medically needed, with small incisions and faster recovery.','جراحة منظار دقيقة عند الحاجة لاستئصال الرحم بأمان وراحة.','Precise keyhole surgery when hysterectomy is needed, done safely and comfortably.','في بعض الحالات المرضية يكون استئصال الرحم هو الخيار الأنسب. نجريه بالمنظار كلما أمكن لتقليل الألم وفترة النقاهة.','In some conditions a hysterectomy is the most suitable option. We perform it laparoscopically whenever possible to reduce pain and recovery time.','[{\"body_ar\":\"يُنصح به في حالات مثل الأورام الكبيرة أو النزيف المزمن الذي لا يستجيب للعلاج أو بعض أمراض الرحم، بعد مناقشة كل البدائل.\",\"body_en\":\"It is advised for cases such as large tumors, chronic bleeding unresponsive to treatment, or certain uterine conditions, after discussing all alternatives.\",\"heading_ar\":\"متى يُنصح به؟\",\"heading_en\":\"When is it advised?\"},{\"body_ar\":\"يوفر جروحًا أصغر وألمًا أقل وإقامة أقصر وعودة أسرع للحياة الطبيعية.\",\"body_en\":\"It offers smaller incisions, less pain, a shorter stay and a faster return to normal life.\",\"heading_ar\":\"لماذا المنظار؟\",\"heading_en\":\"Why laparoscopy?\"}]','[{\"ar\":\"جروح صغيرة وألم أقل\",\"en\":\"Small incisions and less pain\"},{\"ar\":\"إقامة أقصر بالمستشفى\",\"en\":\"Shorter hospital stay\"},{\"ar\":\"تعافٍ أسرع\",\"en\":\"Faster recovery\"}]','[{\"a_ar\":\"نناقش دائمًا كل البدائل الممكنة، ولا نلجأ للاستئصال إلا عند الضرورة الطبية.\",\"a_en\":\"We always discuss every possible alternative and only proceed when medically necessary.\",\"q_ar\":\"هل يوجد بديل عن استئصال الرحم؟\",\"q_en\":\"Is there an alternative to hysterectomy?\"},{\"a_ar\":\"عادة أسرع مع المنظار، مع عودة تدريجية للنشاط خلال أسابيع قليلة.\",\"a_en\":\"Usually faster with laparoscopy, with a gradual return to activity over a few weeks.\",\"q_ar\":\"كم تستغرق النقاهة؟\",\"q_en\":\"How long is recovery?\"}]','استئصال الرحم بالمنظار | د. أحمد مرزوق','Laparoscopic Hysterectomy | Dr. Ahmed Marzouk','استئصال الرحم بالمنظار عند الحاجة بجروح صغيرة وتعافٍ أسرع مع د. أحمد مرزوق.','Laparoscopic hysterectomy when needed, with small incisions and faster recovery with Dr. Ahmed Marzouk.','2026-07-26 11:44:44','2026-08-09 11:47:43'),
('c5338ad1-76f3-4898-9229-91692593f285','endometriosis-care','بطانة-الرحم-المهاجرة','endometriosis-care','73b6f1f5-fbfc-43f2-b2c1-6463aafa663d',NULL,0,1,1,'✿','/uploads/1787755100034-82ac48cf.webp','/uploads/1787755100535-d5e43e02.webp','auto','auto','جراحة أورام','Tumor surgery','بطانة الرحم المهاجرة','Endometriosis Care','تشخيص دقيق وعلاج متخصص لحالات بطانة الرحم المهاجرة، للتخلص من الألم المزمن واستعادة جودة الحياة.','Precise diagnosis and specialized treatment for endometriosis — relief from chronic pain and a better quality of life.','تشخيص دقيق وعلاج متخصص لبطانة الرحم المهاجرة لاستعادة جودة حياتك.','Precise diagnosis and specialized treatment for endometriosis to restore your quality of life.','بطانة الرحم المهاجرة حالة مزمنة كثيرًا ما يتأخر تشخيصها لسنوات. نقدم تشخيصًا دقيقًا وخطة علاج متخصصة تهدف إلى التخلص من الألم المزمن وتحسين فرص الإنجاب.','Endometriosis is a chronic condition whose diagnosis is often delayed for years. We provide accurate diagnosis and a specialized treatment plan aimed at relieving chronic pain and improving fertility prospects.','[{\"body_ar\":\"غالبًا ما تُنسب الأعراض خطأً إلى آلام الدورة الطبيعية، فيتأخر التشخيص. الخبرة المتخصصة تُحدث فرقًا كبيرًا في اكتشاف الحالة مبكرًا.\",\"body_en\":\"Symptoms are often wrongly attributed to normal period pain, so diagnosis is delayed. Specialized experience makes a big difference in catching it early.\",\"heading_ar\":\"لماذا يتأخر التشخيص؟\",\"heading_en\":\"Why is diagnosis delayed?\"},{\"body_ar\":\"تتراوح خيارات العلاج بين الأدوية والتدخل الجراحي حسب شدة الحالة ورغبتك في الإنجاب، وتُوضع الخطة بالتشاور الكامل معكِ.\",\"body_en\":\"Treatment ranges from medication to surgery depending on severity and your fertility goals, with the plan set in full consultation with you.\",\"heading_ar\":\"خيارات العلاج\",\"heading_en\":\"Treatment options\"},{\"body_ar\":\"آلام الدورة الشديدة ليست أمرًا طبيعيًا دائمًا. العلاج المناسب يمكن أن يعيد لكِ حياة أكثر راحة.\",\"body_en\":\"Severe period pain is not always normal. The right treatment can give you a more comfortable life.\",\"heading_ar\":\"الألم ليس قدرًا\",\"heading_en\":\"Pain is not inevitable\"}]','[{\"ar\":\"تشخيص دقيق ومبكر\",\"en\":\"Accurate, early diagnosis\"},{\"ar\":\"تخفيف الألم المزمن\",\"en\":\"Relief from chronic pain\"},{\"ar\":\"تحسين فرص الإنجاب\",\"en\":\"Improved fertility prospects\"},{\"ar\":\"خطة علاج مخصصة\",\"en\":\"A tailored treatment plan\"}]','[{\"a_ar\":\"أبرزها آلام الدورة الشديدة وآلام الحوض المزمنة وأحيانًا صعوبة الحمل.\",\"a_en\":\"The most prominent are severe period pain, chronic pelvic pain, and sometimes difficulty conceiving.\",\"q_ar\":\"ما أعراض بطانة الرحم المهاجرة؟\",\"q_en\":\"What are the symptoms of endometriosis?\"},{\"a_ar\":\"في كثير من الحالات نعم، عبر الأدوية والمتابعة، حسب شدة الحالة.\",\"a_en\":\"In many cases yes, through medication and follow-up, depending on severity.\",\"q_ar\":\"هل يمكن علاجها بدون جراحة؟\",\"q_en\":\"Can it be treated without surgery?\"},{\"a_ar\":\"قد تؤثر على الخصوبة، لكن العلاج المناسب يحسّن الفرص كثيرًا.\",\"a_en\":\"It can affect fertility, but the right treatment greatly improves the chances.\",\"q_ar\":\"هل تؤثر على الحمل؟\",\"q_en\":\"Does it affect pregnancy?\"}]','علاج بطانة الرحم المهاجرة | د. أحمد مرزوق','Endometriosis Care | Dr. Ahmed Marzouk','تشخيص وعلاج بطانة الرحم المهاجرة للتخلص من الألم المزمن مع د. أحمد مرزوق.','Diagnosis and treatment of endometriosis to relieve chronic pain with Dr. Ahmed Marzouk.','2026-07-15 11:22:25','2026-08-09 11:43:43'),
('ea4248bd-c234-4746-bedb-5aa42c8b5bef','laparoscopic-fibroid-removal','استئصال-الأورام-الليفية-بالمنظار','laparoscopic-fibroid-removal','73b6f1f5-fbfc-43f2-b2c1-6463aafa663d',NULL,8,1,1,'✚','/uploads/1787755095238-1d0c3314.webp','/uploads/1787755095780-cd119820.webp','auto','auto','جراحة أورام','Tumor surgery','استئصال الأورام الليفية بالمنظار','Laparoscopic Fibroid Removal','إزالة الأورام الليفية بالمنظار الجراحي بجروح صغيرة وتعافٍ أسرع.','Removing fibroids by laparoscopy through tiny incisions with faster recovery.','جراحة منظار دقيقة بجروح صغيرة وألم أقل وتعافٍ أسرع.','Precise keyhole surgery with tiny incisions, less pain and faster recovery.','يتيح المنظار الجراحي استئصال الأورام الليفية من خلال جروح صغيرة جدًا، مما يقلل الألم وفترة النقاهة مقارنة بالجراحة التقليدية.','Laparoscopy allows fibroid removal through very small incisions, reducing pain and recovery time compared to open surgery.','[{\"body_ar\":\"جروح صغيرة، ألم أقل، إقامة أقصر بالمستشفى، وعودة أسرع للحياة الطبيعية مع ندبات أقل.\",\"body_en\":\"Small incisions, less pain, a shorter hospital stay, and a faster return to normal life with minimal scarring.\",\"heading_ar\":\"مزايا المنظار\",\"heading_en\":\"Benefits of laparoscopy\"},{\"body_ar\":\"يحدد الطبيب مدى ملاءمة المنظار حسب حجم الورم وعدده وموضعه بعد تقييم دقيق.\",\"body_en\":\"The surgeon determines suitability based on the size, number and location of the fibroids after careful assessment.\",\"heading_ar\":\"لمن يناسب؟\",\"heading_en\":\"Who is it suitable for?\"}]','[{\"ar\":\"جروح صغيرة وندبات أقل\",\"en\":\"Small incisions, minimal scarring\"},{\"ar\":\"ألم أقل وتعافٍ أسرع\",\"en\":\"Less pain and faster recovery\"},{\"ar\":\"إقامة أقصر بالمستشفى\",\"en\":\"Shorter hospital stay\"}]','[{\"a_ar\":\"يعتمد ذلك على حجم الورم وموضعه؛ نقيّم كل حالة لاختيار الأنسب.\",\"a_en\":\"It depends on the size and location; we assess each case to choose the best approach.\",\"q_ar\":\"هل المنظار مناسب لكل الأورام؟\",\"q_en\":\"Is laparoscopy suitable for all fibroids?\"},{\"a_ar\":\"عادة أسرع من الجراحة المفتوحة، مع عودة تدريجية خلال أيام إلى أسابيع قليلة.\",\"a_en\":\"Usually faster than open surgery, with a gradual return over days to a few weeks.\",\"q_ar\":\"كم تستغرق فترة التعافي؟\",\"q_en\":\"How long is recovery?\"}]','استئصال الأورام الليفية بالمنظار | د. أحمد مرزوق','Laparoscopic Fibroid Removal | Dr. Ahmed Marzouk','استئصال الأورام الليفية بالمنظار بجروح صغيرة وتعافٍ أسرع مع د. أحمد مرزوق.','Laparoscopic fibroid removal through tiny incisions with faster recovery with Dr. Ahmed Marzouk.','2026-07-26 11:44:44','2026-08-09 11:46:06'),
('eaaa8ee9-ff8e-45a0-9746-7b58518832a4','cosmetic-gynecology','التجميل-النسائي','cosmetic-gynecology','2300aca2-e93f-48d3-8316-6f683a6660ac',NULL,5,1,1,'✦','/uploads/1787755093789-eab3d898.webp','/uploads/1787755094074-33378116.webp','span 2','auto','تجميل','Cosmetic','التجميل النسائي','Cosmetic Gynecology','جراحات تجميل نسائي دقيقة تعيد الثقة والراحة، بأحدث التقنيات وبخصوصية تامة.','Precise cosmetic gynecology procedures that restore confidence and comfort, with full privacy and the latest techniques.','جراحات تجميل نسائي دقيقة تعيد لكِ الثقة والراحة بخصوصية تامة.','Precise cosmetic gynecology that restores your confidence and comfort with complete privacy.','نقدم مجموعة من إجراءات التجميل النسائي الدقيقة التي تهدف إلى استعادة الثقة والراحة، بأحدث التقنيات وضمن بيئة تحترم خصوصيتك تمامًا.','We offer a range of precise cosmetic gynecology procedures aimed at restoring confidence and comfort, with the latest techniques in an environment that fully respects your privacy.','[{\"body_ar\":\"نتعامل مع كل حالة بأقصى درجات السرية والاحترام، لأن راحتك وثقتك أولوية.\",\"body_en\":\"We handle every case with the utmost confidentiality and respect — your comfort and confidence are a priority.\",\"heading_ar\":\"خصوصية تامة\",\"heading_en\":\"Complete privacy\"},{\"body_ar\":\"نستخدم تقنيات حديثة تقلل من فترة التعافي وتضمن نتائج طبيعية ومريحة.\",\"body_en\":\"We use modern techniques that reduce recovery time and ensure natural, comfortable results.\",\"heading_ar\":\"أحدث التقنيات\",\"heading_en\":\"The latest techniques\"},{\"body_ar\":\"نبدأ دائمًا باستشارة صريحة نشرح فيها الخيارات والتوقعات بوضوح قبل أي قرار.\",\"body_en\":\"We always start with an open consultation explaining the options and expectations clearly before any decision.\",\"heading_ar\":\"استشارة صريحة\",\"heading_en\":\"An open consultation\"}]','[{\"ar\":\"استعادة الثقة والراحة\",\"en\":\"Restored confidence and comfort\"},{\"ar\":\"خصوصية واحترام كامل\",\"en\":\"Full privacy and respect\"},{\"ar\":\"أحدث التقنيات وأقل تعافٍ\",\"en\":\"Latest techniques, minimal recovery\"},{\"ar\":\"نتائج طبيعية\",\"en\":\"Natural results\"}]','[{\"a_ar\":\"نعم، نضمن أعلى درجات الخصوصية والسرية لكل مريضة.\",\"a_en\":\"Yes — we guarantee the highest privacy and confidentiality for every patient.\",\"q_ar\":\"هل الإجراءات سرية تمامًا؟\",\"q_en\":\"Are the procedures fully confidential?\"},{\"a_ar\":\"تختلف حسب الإجراء، لكن التقنيات الحديثة تقلل فترة التعافي كثيرًا.\",\"a_en\":\"It varies by procedure, but modern techniques greatly shorten recovery.\",\"q_ar\":\"كم تستغرق فترة التعافي؟\",\"q_en\":\"How long is recovery?\"},{\"a_ar\":\"من خلال استشارة صريحة نحدد معًا الخيار الأنسب لحالتك.\",\"a_en\":\"Through an open consultation we determine together the best option for your case.\",\"q_ar\":\"كيف أعرف الإجراء المناسب لي؟\",\"q_en\":\"How do I know which procedure suits me?\"}]','التجميل النسائي | د. أحمد مرزوق','Cosmetic Gynecology | Dr. Ahmed Marzouk','جراحات التجميل النسائي بأحدث التقنيات وخصوصية تامة مع د. أحمد مرزوق.','Cosmetic gynecology with the latest techniques and complete privacy with Dr. Ahmed Marzouk.','2026-07-15 11:22:25','2026-08-09 11:45:39');
