('4754434b-a5e9-4b5d-b504-705a256f3130','contact.reqName','برجاء إدخال الاسم ورقم الهاتف.','Please enter your name and phone number.','Contact page','2026-07-20 08:04:59'),
('49b6d71f-acbe-4037-aae0-c028167f202f','contact.fMsg','رسالتك (اختياري)','Your message (optional)','Contact page','2026-07-20 08:04:59'),
