INSERT INTO `testimonials` VALUES
('0f3d5d78-740d-43c1-aa55-349cda85e255',3,1,1,0,'','وحابه اشكرك والله علي سعه صدرك لاسئلتي اولا\n\nوثانيا تصميمك انك متفتحتش في ميه جزء تفتح علي جزء متاكد انها هتكون موجودة وده بيدل علي انسانيتك 🌹 مش مجرد عملية وخلاص ❤️\n\n+اني حاسه ولا كاني عامله حاجه ماما عماله تقولي طب مثلي انك بتتوجعي قدام الناس 😂 وانا والله زي الفل 😂😂\n\nربنا يحسن ما بين ايديك يارب وتفضل افضل دكتور في المجرة يارب\n\nبشكرك من هنا للسنه الجايه والله ومع كل مره هتجيلي فيها البريود من غير الوجع ده تاني اكيد هفتكرك العمليه السكر دي وادعيلك','First of all, I really want to thank you for being so patient and answering all my questions.\n\nSecondly, I really admire how you didn’t make unnecessary incisions or open up multiple areas just to look for something that you were already confident would be there. That says a lot about your humanity. 🌹 You care about the person, not just the operation. ❤️\n\nPlus, I honestly feel like I haven’t even had surgery. My mother keeps telling me, “At least pretend that you’re in pain in front of people!” 😂 But I swear I feel perfectly fine. 😂😂\n\nMay God bless your hands and keep you the best doctor in the galaxy! 🙏\n\nThank you from now until next year. Every time I get my period without that pain again, I will definitely remember this wonderful surgery and pray for you.','2026-08-09 12:07:46','2026-08-09 12:07:51'),
('382ea153-3777-43fc-ad42-f620a01cff33',9,1,1,5,'Martina Louise','طبيب جيد يتمتع بروح الدعابة، لكن العيادة قديمة بعض الشيء، وأنا أفضل عيادة القاهرة الجديدة.','Good doctor with sense of humor, the clinic is a bit old, I like the new Cairo clinic better.','2026-07-21 06:22:13','2026-08-09 12:08:47'),
('3d448b84-929a-4b0e-be9f-ef1538070ca9',11,1,1,4,'Nada Anwer','من احسن الاطباء و من نجاح آلي نجاح\n','One of the best doctors—going from success to success.','2026-07-21 06:23:55','2026-08-09 12:08:47'),
('45af6b64-3b80-4f44-a2ff-ae056f9af8b5',0,1,1,0,'','كل سنه وانت طيب يا دكتور يا اشطر حد شوفته في حياتي بجد ربنا يديمها عليك نعمه ويديمك نعمه لينا انا بجد بسمع تجارب صحابي بقولهم ده انا شايله ورم والد ولا كاني دخلت عمليات اصلا 😂😂\n\nعيد سعيد عليك وعلى كل حبايبك يارب ❤️🐑','Happy Eid, Doctor! You are honestly the best doctor I have ever met. May God always bless you with this gift and continue to make you a blessing to us. I hear my friends’ experiences and tell them, “I had a fibroid removed, and it feels like I never even had surgery!” 😂😂\n\nHappy Eid to you and all your loved ones ❤️🐑','2026-08-09 12:05:16','2026-08-09 12:06:17'),
('5c7819d7-0f41-431f-8b69-d428c29bb942',1,1,1,0,'','احسن واشطر دكتور في العالم كله مش ف مصر بس\nبروفيسور احمد مرزوق\n\nتستاهل كل خير بجد لحضرتك فضل كبير اني اخلص من ورم ليفي قعدت ادور ٧ سنين علي دكتور يشيله بدون استئصال للرحم ولحظتي الحلوه اوي بيساء ربنا اني اوصل لحضرتك من البحر الاحمر واجيك واتخلص منه اثناء ولادة توأمي الغاليين وكمان اتخلص من الورم والرحم موجود وعدي ٥ سنين وانا زي الفل ولا حسيت بأي شيء لا اثناء العمليه ولا بعدها ربنا يوفقك ويكرمك يارب ويجازيك عنا كل خيررر بالتوفيق دايما يارب 🌹🌹🌹🌹🌹🌹\n\nحقيقي انت الاستاذ 👏👏👏💪💪💪','The best and most brilliant doctor in the whole world, not just in Egypt.\nProfessor Ahmed Marzouk.\n\nYou truly deserve all the best. You played a huge role in helping me finally get rid of a fibroid. I had been searching for seven years for a doctor who could remove it without removing my uterus. I was so incredibly lucky that God guided me to you from the Red Sea, and I was able to have it removed while giving birth to my precious twins.\n\nYou removed the fibroid while preserving my uterus, and five years have passed since then. I feel completely fine and have not experienced any problems, either during the surgery or afterward. May God grant you success, bless you, and reward you for everything you have done for us. Wishing you continued success always. 🌹🌹🌹🌹🌹🌹\n\nYou truly are a master! 👏👏👏💪💪💪','2026-08-09 12:06:49','2026-08-09 12:06:55'),
('68c88e94-2320-4e7e-81aa-6e204c760568',7,1,1,5,'Ràbáb Zäkriá','ما شاء الله عليك فعلًا. كفاية ضحكتك في وشنا، وفعلًا بجد ما حسيتش بحاجة وما شفتش مكان الجرح. بارك الله فيك وتسلم إيدك أنت والفريق كله.','Honestly amazing. Your smile alone was enough — I truly felt nothing and never even noticed the scar. Bless you and the whole team.','2026-07-15 11:22:26','2026-08-09 12:08:47'),
('728eb711-24a9-4abd-ab4d-9329bb1bd2ae',12,1,1,4,'Nada Anwer','دكتور ممتاز\n','Excellent doctor.','2026-07-21 06:24:27','2026-08-09 12:08:47'),
('8ac388a0-be1c-43d3-b8da-9a50c905f777',10,1,1,5,'Bahaa Taman','افضل دكتور في مصر ماشاء الله شاطر جدا\n','The best doctor in Egypt—truly excellent, mashallah.','2026-07-21 06:23:23','2026-08-09 12:08:47'),
('a33eede5-8481-401f-84b0-5731b14b6525',4,1,1,0,'','السلام عليكم دكتور احمد ازيك انا شايبة بنت خال منار اللي عملت لي العملية التلات الفات\n\nانا اولا عايزة اشكرك جدا جدا على العملتو معاي انا كنت في حيرة والم سنين وسنين ربنا ينفعك بعلمك ويزيدك يارب ❤️\n\nمع انو المقابلة بعد العملية لسه تاني اسبوع بس حاسة اني عايزة اشكرك.. كلمتني منار عايزني اعمل اشعة تاني بعد شهر عشان نتأكد اكتر من كل حاجة تمام عندي اسئلة كتير بس لحدي ما نتلاقى الاسبوع الجاي ان شاءالله 🥰','Hello Dr. Ahmed, how are you? I’m Manar’s cousin, the one who had the operation a few days ago.\n\nFirst of all, I want to thank you so, so much for what you did for me. I had been suffering and confused for years and years. May God bless you for your knowledge and increase you in success. ❤️\n\nEven though it has only been the second week since the operation, I already feel like I want to thank you. Manar told me that you want me to have another scan after a month so we can make sure everything is okay. I still have so many questions, but I’ll see you next week, God willing. 🥰','2026-08-09 12:08:10','2026-08-09 12:08:14'),
('af2a14a6-a9b2-4dae-91e6-d92056b55c01',8,1,1,5,'Semsema Ali','من شطارتك يا دكتوري خلتني أنزل أولد في مصر وأرجع تاني. كنت بسمع عن المعاناة، لكن لما ولدت معاك الموضوع اتغير تمامًا.','Your skill made me travel to Egypt just to deliver with you — and I would do it again. Everything I feared about birth changed completely.','2026-07-15 11:22:26','2026-08-09 12:08:47'),
('bd48e0cc-725c-42bb-8d85-edf1d9c025fc',5,1,1,0,'','(اول شي احمد ربي انه حطك ف طريقي\nوعرفت افضل دكتور جايه من السعوديه عشان نتيجه معينه شفت افضل افضل نتيجه وتعامل منك انت دكتور مبدع وفعلا كل شي عندك بدون الم..... طبعا لازم بنكمل ونقهر بطانه الرحم اللي شلتها بتكملت علاجي معاك باذن الله 🌷🌷🌷\n\nوترشيحك ليا دكتور محمد بياني كان حاجه اشكرك عليها والله طول العمر نجاح وساحر للجسم بعد التكميم\n\nشكراا ع كل شي انا جايتك العياده طبعا بس مو قادره انتظر م اكتب واشكرك ع كل شي جميل منك انت وكل الطاقم اللي معاك 🌷🌷🌷💐💐💐)','First of all, I thank God for putting you in my path.\nI came from Saudi Arabia looking for the best doctor because I wanted a specific result, and I saw the best possible result and the best treatment from you. You are an amazing doctor, and everything you do is truly exceptional. There was no unnecessary pain or suffering. Of course, we still need to continue and finally overcome the uterine lining problem that you treated for me, and I will continue my treatment with you, God willing. 🌷🌷🌷\n\nAnd your recommendation of Dr. Mohamed Bayani was something I will be grateful to you for forever. He is excellent and wonderful with the body after gastric sleeve surgery.\n\nThank you for everything. I came to the clinic, of course, but I couldn’t wait to write and thank you for everything wonderful you have done, and for all the amazing energy you and your entire team have. 🌷🌷🌷💐💐💐','2026-08-09 12:08:39','2026-08-09 12:08:47'),
('c220d69e-833c-4b1c-b887-ce5f2ed73f7a',2,1,1,0,'','انا روحت يادكتوري العظيم\nكنت محتاجه اعرف منك البطانه كانت متشبعه ازاي وهل مكنش باين في اي اشاعه عملناها؟\nواي الكميه الي طالعه دي 😂 ده انا جبل اني استحملت كل ده 😂😂😂','I came to you, my amazing doctor.\nI wanted to ask how severe the uterine lining issue was and whether it wasn’t visible in any of the scans we had done?\n\nAnd what is this huge amount that came out? 😂 I must be made of steel to have endured all of that! 😂😂😂','2026-08-09 12:07:15','2026-08-09 12:07:22'),
('d8388edb-9c0a-48d5-9c52-f31d8a545613',6,1,1,5,'Rana Sayed','ربنا يباركلك ويكتر من أمثالك. بجد أنت راجل خلوق ومطمئن، بحمد ربنا دايمًا إنه حطك في طريقي عشان أولد معاك بدون ألم.','God bless you. You are truly kind and reassuring — I always thank God He put you in my path so I could deliver with you without pain.','2026-07-15 11:22:26','2026-08-09 12:08:47');
