INSERT INTO `value_items` VALUES
('153e85f0-45b2-4acb-8b4f-377ec15f1803',3,1,'03','قيمنا','Our Values','التميز في الرعاية الصحية النسائية، والتطور بتطبيق التكنولوجيا المبتكرة في الوقت المناسب، والنزاهة باتباع الأسس الأخلاقية في كل قرار.','Excellence in women’s healthcare, progress through innovative technology delivered at the right time, and integrity in every decision.','2026-07-16 09:43:28','2026-07-20 08:52:03'),
('1bd72358-10ff-42bb-9f2b-d75ae6d7ec61',2,1,'02','رؤيتنا','Our Vision','أن تكون كل زيارة استشارة إيجابية وبناءة؛ نقدم مستوى رعاية لائقًا وفريدًا يريح المرأة جسديًا ونفسيًا في مجال أمراض النساء والتوليد.','Every visit should be a positive, constructive consultation — a unique standard of care that puts women at ease, physically and emotionally.','2026-07-16 09:43:28','2026-07-20 08:52:03'),
('45d3ebd2-7976-48d4-8b55-c4d0790d89a3',1,1,'01','رسالتنا','Our Mission','تقديم علاج متخصص لأمراض النساء والتوليد لدعم المرأة صحيًا، والمساعدة في تحقيق الشفاء التام والسريع، وحماية حقها في الرعاية الإنجابية الكاملة.','Specialized OB-GYN treatment that supports women’s health, helps achieve full and rapid recovery, and protects the right to complete reproductive care.','2026-07-16 09:43:28','2026-07-20 08:52:03');
